<template>
  <section class="sr-content-preview" :aria-label="$t('sr_preview_title')" :aria-busy="state?.loading || false">
    <div class="sr-preview-heading">
      <span>{{ $t('sr_preview_title') }}</span>
      <strong>{{ title }}</strong>
      <span v-if="description" class="sr-preview-description">{{ description }}</span>
      <p>{{ $t('sr_preview_hint') }}</p>
    </div>
    <p v-if="state?.loading" role="status">{{ $t('sr_preview_loading') }}</p>
    <div v-else-if="state?.error" role="alert">
      <p>{{ $t('sr_preview_error') }}</p>
      <button type="button" class="sr-preview-button" @click="$emit('retry')">{{ $t('sr_layout_retry') }}</button>
    </div>
    <template v-else-if="state?.content">
      <p class="sr-preview-count">{{ $t('sr_preview_count', { groups: state.content.groups.length, fields: state.content.fields.length, required: state.content.fields.filter(field => field.required).length }) }}</p>
      <div v-if="!isSelected" class="sr-preview-tabs" role="tablist" :aria-label="$t('sr_preview_title')">
        <button v-for="tab in ['differences', 'structure']" :id="`${panelId}-${tab}-tab`" :key="tab" type="button" role="tab" :aria-selected="activeTab === tab" :aria-controls="`${panelId}-${tab}`" :tabindex="activeTab === tab ? 0 : -1" @click="activeTab = tab" @keydown.left.prevent="switchTab(tab)" @keydown.right.prevent="switchTab(tab)">
          {{ $t(tab === 'differences' ? 'sr_preview_differences' : 'sr_preview_structure') }}
        </button>
      </div>

      <section v-if="!isSelected && activeTab === 'differences'" :id="`${panelId}-differences`" role="tabpanel" :aria-labelledby="`${panelId}-differences-tab`" class="sr-preview-comparison" :aria-label="$t('sr_preview_compare')">
        <h4>{{ $t('sr_preview_compare') }}</h4>
        <p class="sr-preview-baseline">{{ selectedTitle }}</p>
        <p v-if="selectedState?.loading" role="status">{{ $t('sr_preview_compare_loading') }}</p>
        <div v-else-if="!comparison">
          <p>{{ $t('sr_preview_compare_unavailable') }}</p>
          <button v-if="selectedState?.error" type="button" class="sr-preview-button" @click="$emit('retry-selected')">{{ $t('sr_layout_retry') }}</button>
        </div>
        <template v-else>
          <p v-if="!hasDifferences">{{ $t('sr_preview_identical') }}</p>
          <dl v-else class="sr-differences">
            <template v-if="comparison.added.length">
              <dt>{{ $t('sr_preview_added') }}</dt>
              <dd>{{ comparison.added.map(field => field.label).join(', ') }}</dd>
            </template>
            <template v-if="comparison.removed.length">
              <dt>{{ $t('sr_preview_removed') }}</dt>
              <dd>{{ comparison.removed.map(field => field.label).join(', ') }}</dd>
            </template>
            <template v-for="change in comparison.changed" :key="change.field.key">
              <dt>{{ $t('sr_preview_changed') }}: {{ change.field.label }}</dt>
              <dd>
                <div v-for="property in change.properties" :key="property.key">
                  {{ propertyLabel(property.key) }}: {{ valueLabel(property.before) }} → {{ valueLabel(property.after) }}
                </div>
              </dd>
            </template>
            <template v-if="comparison.structureChanged">
              <dt>{{ $t('sr_preview_structure') }}</dt>
              <dd v-if="comparison.groupNamesChanged">
                {{ selectedState?.content?.groups.map(group => group.label).join(', ') || $t('sr_preview_unset') }} → {{ state.content.groups.map(group => group.label).join(', ') || $t('sr_preview_unset') }}
              </dd>
              <dd v-else>{{ $t('sr_preview_structure_changed') }}</dd>
            </template>
            <template v-if="comparison.settings.length">
              <dt>{{ $t('sr_preview_settings') }}</dt>
              <dd v-for="setting in comparison.settings" :key="setting.key">
                {{ propertyLabel(setting.key) }}: {{ valueLabel(setting.before) }} → {{ valueLabel(setting.after) }}
              </dd>
            </template>
          </dl>
        </template>
      </section>

      <div v-if="isSelected || activeTab === 'structure'" :id="`${panelId}-structure`" :role="isSelected ? undefined : 'tabpanel'" :aria-labelledby="isSelected ? undefined : `${panelId}-structure-tab`" class="sr-preview-outline">
        <h4>{{ $t('sr_preview_structure') }}</h4>
        <p v-if="!state.content.fields.length">{{ $t('sr_preview_empty') }}</p>
        <section v-for="group in state.content.groups" :key="group.key" class="sr-preview-group">
          <h5>{{ group.label }}</h5>
          <div class="sr-preview-fields">
            <div v-for="(field, index) in group.fields" :key="`${field.key}-${index}`" class="sr-preview-field" :class="{ 'sr-preview-field--hidden': field.hidden }" :style="{ flexBasis: `calc(${field.width}% - 8px)` }">
              <strong>{{ field.label }}</strong>
              <span>{{ field.type }}</span>
              <span v-if="field.required" class="sr-preview-flag">{{ $t('sr_preview_required') }}</span>
              <span v-if="field.readonly" class="sr-preview-flag">{{ $t('sr_preview_readonly') }}</span>
              <span v-if="field.hidden" class="sr-preview-flag">{{ $t('sr_preview_hidden') }}</span>
            </div>
          </div>
        </section>
      </div>
    </template>
    <p v-else>{{ $t('sr_preview_loading') }}</p>
    <div class="sr-preview-footer">
      <button v-if="!isSelected" type="button" class="sr-preview-button sr-preview-select" @click="$emit('select')">{{ $t('sr_preview_select') }}</button>
      <p v-else class="sr-preview-current">{{ $t('sr_layout_selected') }}</p>
    </div>
  </section>
</template>

<script lang="ts">
import { defineComponent, useId, type PropType } from 'vue';
import { compareLayoutPreviews, type PreviewState } from './layout-preview.model';

export default defineComponent({
  name: 'LayoutContentPreview',
  props: {
    title: { type: String, required: true },
    description: { type: String, default: '' },
    selectedTitle: { type: String, default: '' },
    isSelected: { type: Boolean, default: false },
    state: { type: Object as PropType<PreviewState>, default: undefined },
    selectedState: { type: Object as PropType<PreviewState>, default: undefined },
  },
  emits: ['select', 'retry', 'retry-selected'],
  setup() { return { panelId: `layout-content-${useId()}` }; },
  data() { return { activeTab: 'differences' }; },
  computed: {
    comparison() {
      return this.state?.content && this.selectedState?.content
        ? compareLayoutPreviews(this.selectedState.content, this.state.content) : null;
    },
    hasDifferences(): boolean {
      const c = this.comparison;
      return !!c && !!(c.added.length || c.removed.length || c.changed.length || c.settings.length || c.structureChanged);
    },
  },
  methods: {
    switchTab(current: string) {
      this.activeTab = current === 'differences' ? 'structure' : 'differences';
      this.$nextTick(() => {
        (this.$el as HTMLElement).querySelector<HTMLButtonElement>(`#${this.panelId}-${this.activeTab}-tab`)?.focus();
      });
    },
    propertyLabel(key: string): string {
      key = key.split('.').at(-1) || key;
      const known: Record<string, string> = { isRequired: 'sr_preview_required', is_hidden: 'sr_preview_hidden', isHidden: 'sr_preview_hidden', is_readonly: 'sr_preview_readonly', isDisabled: 'sr_preview_disabled', elementWidth: 'sr_preview_width', fieldType: 'sr_preview_type', general_settings: 'sr_preview_settings', auto_generate_tab_index: 'sr_preview_tab_order', disable_extraction_confirmation_box: 'sr_preview_confirmation', validation_time_spent_counter: 'sr_preview_timer' };
      if (known[key]) return this.$t(known[key]);
      const translated = this.$t(key);
      return translated !== key ? translated : key.replace(/([a-z])([A-Z])/g, '$1 $2').replace(/_/g, ' ');
    },
    valueLabel(value: unknown): string {
      if (value === undefined || value === null || value === '') return this.$t('sr_preview_unset');
      if (typeof value === 'boolean') return this.$t(value ? 'sr_preview_yes' : 'sr_preview_no');
      if (typeof value === 'object') return JSON.stringify(value);
      return String(value);
    },
  },
});
</script>

<style scoped>
.sr-content-preview { min-width: 0; padding: 16px; border: 1px solid var(--sr-border-strong); border-radius: 8px; background: var(--sr-surface); color: var(--sr-ink); font-size: 13px; line-height: 1.5; overflow-wrap: anywhere; max-height: 640px; overflow-y: auto; overscroll-behavior: contain; box-sizing: border-box; }
.sr-preview-heading { display: flex; flex-direction: column; gap: 6px; }
.sr-preview-heading > span { font-weight: 600; color: var(--sr-muted); }
.sr-preview-heading > strong { font-size: 15px; }
.sr-content-preview p { margin: 8px 0 12px; }
.sr-preview-heading p, .sr-preview-baseline { color: var(--sr-muted); }
.sr-preview-count { font-weight: 600; }
.sr-preview-tabs { display: flex; gap: 8px; margin: 16px 0; border-bottom: 1px solid var(--sr-border); }
.sr-preview-tabs button { min-height: 44px; border: 0; border-bottom: 2px solid transparent; color: var(--sr-muted); background: transparent; font: inherit; padding: 8px 12px; cursor: pointer; }
.sr-preview-tabs button[aria-selected="true"] { color: var(--sr-ink); border-bottom-color: var(--sr-accent); font-weight: 600; }
.sr-preview-tabs button:focus-visible { outline: 2px solid var(--sr-accent); outline-offset: -2px; }
.sr-content-preview h4 { margin: 0 0 8px; font-size: 14px; font-weight: 600; }
.sr-preview-comparison { padding: 16px 0; margin: 12px 0 16px; border-top: 1px solid var(--sr-border); border-bottom: 1px solid var(--sr-border); }
.sr-differences { margin: 0; }
.sr-differences dt { font-weight: 600; margin-top: 12px; }
.sr-differences dd { margin: 4px 0 0; }
.sr-preview-group { margin-top: 14px; }
.sr-preview-group h5 { font-size: 13px; margin: 0 0 8px; font-weight: 600; }
.sr-preview-fields { display: flex; flex-wrap: wrap; gap: 8px; }
.sr-preview-field { flex-grow: 1; min-width: min(140px, 100%); padding: 8px 10px; border: 1px solid var(--sr-border-strong); border-radius: 4px; box-sizing: border-box; display: flex; flex-direction: column; gap: 4px; background: var(--sr-surface-2); }
.sr-preview-field--hidden { border-style: dashed; }
.sr-preview-field > span { color: var(--sr-muted); font-size: 12px; }
.sr-preview-field .sr-preview-flag { color: var(--sr-ink); font-weight: 600; }
.sr-preview-button { min-height: 44px; border: 1px solid var(--sr-border-strong); border-radius: 6px; background: var(--sr-surface); color: var(--sr-ink); padding: 8px 12px; font: inherit; cursor: pointer; }
.sr-preview-button:hover { background: var(--sr-surface-2); }
.sr-preview-button:focus-visible { outline: 2px solid var(--sr-accent); outline-offset: 2px; }
.sr-preview-footer { position: sticky; bottom: -16px; background: var(--sr-surface); padding: 12px 0; border-top: 1px solid var(--sr-border); margin-top: 18px; }
.sr-preview-select { width: 100%; border-color: var(--sr-accent); font-weight: 600; }
.sr-content-preview .sr-preview-current { font-weight: 600; margin: 16px 0 0; }
</style>
