<template>
  <div class="sr-target-picker">
    <div v-if="modelValue" class="sr-selected" data-test="sr-selected-layout">
      <Icon icon="mdi:check-circle-outline" width="20" height="20" aria-hidden="true" />
      <div class="sr-selected-text">
        <span class="sr-selected-label">{{ $t('sr_layout_selected') }}</span>
        <strong>{{ selectedOption?.label || selectedTitle || modelValue }}</strong>
        <span v-if="selectedOption" class="sr-layout-meta">{{ metadata(selectedOption) }}</span>
        <span class="sr-layout-id">{{ $t('sr_layout_identifier') }}: {{ modelValue }}</span>
        <span v-if="!loading && !loadError && !selectedOption" class="sr-layout-meta">
          {{ $t('sr_layout_unavailable') }}
        </span>
      </div>
    </div>

    <div class="sr-picker-toolbar">
      <div class="sr-layout-search">
        <Icon icon="mdi:magnify" width="20" height="20" aria-hidden="true" />
        <input
          ref="searchInput"
          v-model="searchQuery"
          type="search"
          :placeholder="$t('sr_layout_search_placeholder')"
          :aria-label="$t('sr_layout_search')"
          data-test="sr-layout-search"
        />
        <button v-if="searchQuery" type="button" class="sr-search-clear" :aria-label="$t('sr_layout_clear_search')" @click="clearSearch">
          <Icon icon="mdi:close" width="18" height="18" aria-hidden="true" />
        </button>
      </div>
      <span v-if="!loading && !loadError" class="sr-result-count" role="status" aria-live="polite">
        {{ $t('sr_layout_result_count', { count: filteredOptions.length, total: options.length }) }}
      </span>
    </div>

    <p v-if="loading" class="sr-picker-message" role="status">{{ $t('sr_layout_loading') }}</p>
    <div v-else-if="loadError" class="sr-picker-message" role="alert">
      <p>{{ $t('sr_layout_load_error') }}</p>
      <button type="button" class="sr-picker-reset" @click="$emit('retry')">{{ $t('sr_layout_retry') }}</button>
    </div>
    <div v-else-if="!filteredOptions.length" class="sr-picker-message" role="status">
      <p>{{ $t(options.length ? 'sr_layout_no_matches' : 'no_layouts_available') }}</p>
      <button v-if="searchQuery" type="button" class="sr-picker-reset" @click="clearSearch">{{ $t('sr_layout_clear_search') }}</button>
    </div>
    <div v-else class="sr-picker-content" :class="{ 'sr-picker-content--preview': loadDetails && activePreviewId }">
      <fieldset class="sr-layout-list" :aria-label="$t('target_layout')">
        <div v-for="opt in filteredOptions" :key="opt.value" class="sr-option">
          <label
            class="sr-choice"
            :class="{ 'sr-choice--on': modelValue === opt.value }"
            :data-test="'sr-layout-' + opt.value"
          >
            <input
              type="radio"
              :name="radioGroupName"
              :value="opt.value"
              :checked="modelValue === opt.value"
              @change="$emit('update:modelValue', opt.value)"
            />
            <span class="sr-choice-text">
              <strong>{{ opt.label }}</strong>
              <span class="sr-layout-meta">{{ metadata(opt) }}</span>
              <span v-if="duplicateTitles.has(normalize(opt.label))" class="sr-layout-id">
                {{ $t('sr_layout_identifier') }}: {{ opt.value }}
              </span>
            </span>
            <span v-if="modelValue === opt.value" class="sr-choice-selected">{{ $t('sr_layout_selected_short') }}</span>
          </label>
          <button
            v-if="loadDetails"
            type="button"
            class="sr-preview-open"
            :class="{ 'sr-preview-open--active': activePreviewId === opt.value }"
            :aria-label="$t('sr_preview_open_name', { name: [opt.label, metadata(opt), duplicateTitles.has(normalize(opt.label)) ? opt.value : ''].filter(Boolean).join(' · ') })"
            :aria-controls="`${radioGroupName}-preview`"
            :aria-pressed="activePreviewId === opt.value"
            @click="inspectLayout(opt.value)"
          >{{ $t('sr_preview_open') }}</button>
        </div>
      </fieldset>
      <LayoutContentPreview
        v-if="loadDetails && activePreviewId"
        :key="activePreviewId"
        :id="`${radioGroupName}-preview`"
        :title="options.find(opt => opt.value === activePreviewId)?.label || selectedTitle || activePreviewId"
        :description="previewOption ? metadata(previewOption) : ''"
        :selected-title="selectedOption ? `${selectedOption.label} · ${metadata(selectedOption)}` : selectedTitle || modelValue"
        :is-selected="activePreviewId === modelValue"
        :state="detailStates[activePreviewId]"
        :selected-state="detailStates[modelValue]"
        @select="$emit('update:modelValue', activePreviewId)"
        @retry="ensureDetails(activePreviewId, true)"
        @retry-selected="ensureDetails(modelValue, true)"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, useId, type PropType } from 'vue';
import LayoutContentPreview from './LayoutContentPreview.vue';
import type { LayoutPreview, PreviewState } from './layout-preview.model';

export interface TargetLayoutOption {
  label: string;
  value: string;
  type: string;
  origin?: string;
  source?: string;
}

const normalize = (value: string) => value.normalize('NFKD').replace(/\p{M}/gu, '').toLocaleLowerCase().trim();

export default defineComponent({
  name: 'TargetLayoutPicker',
  components: { LayoutContentPreview },
  props: {
    options: { type: Array as PropType<TargetLayoutOption[]>, required: true },
    modelValue: { type: String, default: '' },
    selectedTitle: { type: String, default: '' },
    loading: { type: Boolean, default: false },
    loadError: { type: Boolean, default: false },
    loadDetails: { type: Function as PropType<(id: string) => Promise<LayoutPreview>> },
  },
  emits: ['update:modelValue', 'retry'],
  setup() {
    return { radioGroupName: `target-layout-${useId()}` };
  },
  data() {
    return { searchQuery: '', previewId: '', detailStates: {} as Record<string, PreviewState> };
  },
  watch: {
    modelValue: {
      immediate: true,
      handler(value: string) {
        this.previewId = value;
        this.ensureDetails(value);
      },
    },
  },
  computed: {
    activePreviewId(): string { return this.previewId || this.modelValue; },
    previewOption(): TargetLayoutOption | undefined {
      return this.options.find(opt => opt.value === this.activePreviewId);
    },
    selectedOption(): TargetLayoutOption | undefined {
      return this.options.find((opt) => opt.value === this.modelValue);
    },
    filteredOptions(): TargetLayoutOption[] {
      const terms = normalize(this.searchQuery).split(/\s+/).filter(Boolean);
      return this.options.filter((opt) => {
        const text = normalize([opt.label, opt.value, opt.type, opt.origin, opt.source].filter(Boolean).join(' '));
        return terms.every((term) => text.includes(term));
      });
    },
    duplicateTitles(): Set<string> {
      const seen = new Set<string>();
      const duplicates = new Set<string>();
      for (const opt of this.options) {
        const title = normalize(opt.label);
        if (seen.has(title)) duplicates.add(title);
        seen.add(title);
      }
      return duplicates;
    },
  },
  methods: {
    normalize,
    inspectLayout(id: string) {
      this.previewId = id;
      this.ensureDetails(id);
      this.ensureDetails(this.modelValue);
      this.$nextTick(() => {
        const root = this.$el as HTMLElement;
        if (root.getBoundingClientRect().width < 760) {
          root.querySelector<HTMLElement>('.sr-content-preview')?.scrollIntoView?.({ block: 'start', behavior: 'auto' });
        }
      });
    },
    async ensureDetails(id: string, retry = false) {
      if (!id || !this.loadDetails || this.detailStates[id]?.loading || (!retry && this.detailStates[id])) return;
      this.detailStates[id] = { loading: true, error: false };
      try {
        const content = await this.loadDetails(id);
        this.detailStates[id] = { loading: false, error: false, content };
      } catch {
        this.detailStates[id] = { loading: false, error: true };
      }
    },
    metadata(opt: TargetLayoutOption): string {
      return [opt.type, opt.source, opt.origin].filter(Boolean).join(' · ');
    },
    clearSearch() {
      this.searchQuery = '';
      (this.$refs.searchInput as HTMLInputElement | undefined)?.focus();
    },
  },
});
</script>

