.sr-layout-search { display: flex; align-items: center; gap: 8px; flex: 1 1 280px; min-width: 0; padding: 0 10px; border: 1px solid var(--sr-border-strong); border-radius: 6px; background: var(--sr-surface); color: var(--sr-muted); }
.sr-layout-search:focus-within { outline: 2px solid var(--sr-accent); outline-offset: 2px; }
