.sr-option .sr-choice { flex: 1 1 220px; min-width: 0; box-sizing: border-box; }
.sr-preview-open { margin: 0 12px 10px 46px; min-height: 44px; border: 1px solid var(--sr-border-strong); border-radius: 6px; background: var(--sr-surface); color: var(--sr-ink); font: inherit; font-size: 13px; padding: 6px 10px; cursor: pointer; }
.sr-preview-open:hover, .sr-preview-open--active { background: var(--sr-surface-2); }
