.sr-picker-reset { border: 1px solid var(--sr-border-strong); border-radius: 6px; padding: 8px 12px; min-height: 44px; background: var(--sr-surface); color: var(--sr-ink); font: inherit; cursor: pointer; }
@media (max-width: 600px) { .sr-choice { padding: 12px; gap: 10px; flex-wrap: wrap; } .sr-choice-selected { margin-left: 28px; flex-basis: calc(100% - 28px); } .sr-selected { padding: 12px; } }
