type Config = Record<string, unknown>;
export type PreviewTranslator = (key: string, params?: Record<string, unknown>) => string;

export interface PreviewField {
  key: string;
  label: string;
  type: string;
  width: number;
  required: boolean;
  hidden: boolean;
  readonly: boolean;
  config: Config;
}
export interface PreviewGroup { key: string; label: string; fields: PreviewField[] }
export interface LayoutPreview {
  groups: PreviewGroup[];
  fields: PreviewField[];
  structure: unknown[];
  settings: Config;
}
export interface PreviewState { loading: boolean; error: boolean; content?: LayoutPreview }

const record = (value: unknown): value is Config => !!value && typeof value === 'object' && !Array.isArray(value);
const enabled = (value: unknown) => value === true || value === 1 || value === 'true';
const humanize = (value: string) => value.replace(/([a-z])([A-Z])/g, '$1 $2').replace(/[_-]+/g, ' ');
const typeKeys: Record<string, string> = { TextInput: 'sr_preview_text', DateInput: 'sr_preview_date', NumberInput: 'sr_preview_number', CheckBox: 'sr_preview_checkbox', LovInput: 'sr_preview_lookup', EnumInput: 'sr_preview_dropdown', LineItemTable: 'sr_preview_table' };

export function previewLabel(node: Config, t: PreviewTranslator, fallback: string): string {
  const key = String(node.translation_key || node.field_name || node.document_name || node.document_key || '');
  for (const candidate of [key, key.toLowerCase()]) {
    if (candidate && t(candidate) !== candidate) return t(candidate);
  }
  return String(node.field_label || node.title || node.label || fallback);
}

// Read the stored configuration without hydrating the builder store or running
// its migration/save path. A missing payload is an error, not an empty layout.
export function buildLayoutPreview(response: unknown, t: PreviewTranslator): LayoutPreview {
  const template = record(response) && record(response.data) && !('layout_json' in response) ? response.data : response;
  if (!record(template) || template.layout_json == null) throw new Error('Missing layout content');
  const json: unknown = typeof template.layout_json === 'string' ? JSON.parse(template.layout_json) : template.layout_json;
  if (!record(json) || !Array.isArray(json.layout)) throw new Error('Invalid layout content');
  const groups: PreviewGroup[] = [];
  const fields: PreviewField[] = [];
  const visit = (nodes: unknown[], path: string, parent?: PreviewGroup): unknown[] => {
    let group = parent;
    return nodes.map((value, index) => {
      if (!record(value)) throw new Error('Invalid layout element');
      const key = String(value.name || value.field_name || value.document_key || `${path}-${index}`);
      if (Array.isArray(value.rows)) {
        const nested: PreviewGroup = { key: `${path}-${index}`, label: previewLabel(value, t, t('sr_preview_group', { count: groups.length + 1 })), fields: [] };
        groups.push(nested);
        const rows = visit(value.rows, nested.key, nested);
        const { rows: _rows, ...config } = value;
        return { config, rows };
      }
      if (!group) {
        group = { key: path, label: t('sr_preview_fields'), fields: [] };
        groups.push(group);
      }
      const width = Number(value.elementWidth);
      const type = String(value.fieldType || t('sr_preview_field'));
      const typeKey = typeKeys[type];
      const field: PreviewField = {
        key, label: previewLabel(value, t, humanize(key)),
        type: typeKey && t(typeKey) !== typeKey ? t(typeKey) : humanize(type),
        width: Number.isFinite(width) && width > 0 ? Math.min(100, width) : 100,
        required: enabled(value.isRequired), hidden: enabled(value.is_hidden) || enabled(value.isHidden),
        readonly: enabled(value.is_readonly) || enabled(value.isDisabled), config: value,
      };
      group.fields.push(field);
      fields.push(field);
      return { key, width: field.width };
    });
  };
  const structure = visit(json.layout, 'root');
  const { layout: _layout, ...settings } = json;
  if (template.extraction_type != null) settings.extraction_type = template.extraction_type;
  return { groups, fields, structure, settings };
}

const stable = (value: unknown): string => {
  if (Array.isArray(value)) return `[${value.map(stable).join(',')}]`;
  if (record(value)) return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${stable(value[key])}`).join(',')}}`;
  return JSON.stringify(value) ?? 'undefined';
};
export interface FieldChange { field: PreviewField; properties: { key: string; before: unknown; after: unknown }[] }
const flattenSettings = (settings: Config, prefix = ''): Config => Object.fromEntries(
  Object.entries(settings).flatMap(([key, value]) => {
    const path = prefix ? `${prefix}.${key}` : key;
    return record(value) && Object.keys(value).length ? Object.entries(flattenSettings(value, path)) : [[path, value]];
  }),
);
export function compareLayoutPreviews(selected: LayoutPreview, candidate: LayoutPreview) {
  const before = new Map(selected.fields.map(field => [field.key, field]));
  const after = new Map(candidate.fields.map(field => [field.key, field]));
  const changed: FieldChange[] = [];
  for (const field of candidate.fields) {
    const old = before.get(field.key);
    if (!old) continue;
    const properties = [...new Set([...Object.keys(old.config), ...Object.keys(field.config)])]
      .filter(key => stable(old.config[key]) !== stable(field.config[key]))
      .map(key => ({ key, before: old.config[key], after: field.config[key] }));
    if (properties.length) changed.push({ field, properties });
  }
  const oldSettings = flattenSettings(selected.settings);
  const newSettings = flattenSettings(candidate.settings);
  const settings = [...new Set([...Object.keys(oldSettings), ...Object.keys(newSettings)])]
    .filter(key => stable(oldSettings[key]) !== stable(newSettings[key]))
    .map(key => ({ key, before: oldSettings[key], after: newSettings[key] }));
  return {
    added: candidate.fields.filter(field => !before.has(field.key)),
    removed: selected.fields.filter(field => !after.has(field.key)), changed, settings,
    groupNamesChanged: stable(selected.groups.map(group => group.label)) !== stable(candidate.groups.map(group => group.label)),
    structureChanged: stable(selected.structure) !== stable(candidate.structure),
  };
}
