          <span>{{ $t('layout_for_x', { layoutType: readableLayoutType }) }}</span>
          <span>{{ $t('checked_at_priority_x', { priority: Number(rule.priority) || 0 }) }}</span>
        </div>
      </div>

      <div class="sr-ed-grid">
        <div class="sr-ed-main">
          <!-- STEP 1 — Scope & priority -->
          <section class="rb-step">
            <div class="rb-step-head">
              <span class="rb-step-eyebrow">{{ $t('step') }} 1</span>
              <span class="rb-step-title">{{ $t('scope_and_priority') }}</span>
              <span class="rb-step-hint">{{ $t('what_the_rule_covers') }}</span>
            </div>
            <div class="sr-field-grid">
              <!-- Name + key lead: what it's called before what it covers.
                   Shared .rb-field/.rb-label, as the transformation builder. -->
              <div class="rb-field">
                <label class="rb-label">{{ $t('rule_name') }}</label>
                <q-input
                  outlined dense class="back-white"
                  v-model="rule.name"
                  :placeholder="$t('name_this_rule')"
                  data-test="sr-name"
                />
              </div>
              <div class="rb-field">
                <label class="rb-label">{{ $t('rule_key') }}</label>
                <!-- Machine key: auto-derived from the name for a NEW rule and
                     read-only until the pencil unlocks it; immutable in edit mode. -->
                <q-input
                  outlined dense class="back-white rb-mono"
                  :model-value="rule.key"
                  :placeholder="$t('from_the_name')"
                  :readonly="ruleKeyReadonly"
                  data-test="sr-key"
                  @update:model-value="onRuleKeyInput"
                >
                  <template v-if="!isEdit && !ruleKeyEditable" #append>
                    <q-icon name="edit" size="xs" class="cursor-pointer" @click="unlockRuleKey">
                      <q-tooltip>{{ $t('edit_rule_key') }}</q-tooltip>
                    </q-icon>
                  </template>
                </q-input>
              </div>

              <!-- Document type and layout type come from the route/tab the user
                   arrived through and are not editable here (unchanged from the
                   drawer) — shown disabled so the scope is still visible. -->
              <div class="sr-field">
                <label>{{ $t('document_type') }}</label>
                <input class="sr-input" :value="docType" disabled />
              </div>
              <div class="sr-field">
                <label>{{ $t('layout_type') }}</label>
                <input class="sr-input" :value="readableLayoutType" disabled />
              </div>
              <div class="sr-field">
                <label>{{ $t('priority') }}</label>
                <input
                  v-model="rule.priority"
                  class="sr-input"
                  type="number"
                  data-test="sr-priority"
                />
                <span class="sr-hint">{{ $t('lower_numbers_checked_first') }}</span>
              </div>
              <!-- Log execution — each evaluation of this rule writes a
                   rule_execution_log entry. As in the validation builder, a
                   blank label keeps the checkbox on the inputs' line. -->
              <div class="sr-field">
                <label aria-hidden="true">&nbsp;</label>
                <div class="sr-check-line">
                  &#8203;<q-checkbox
                    v-model="rule.logExecution"
                    :label="$t('log_execution')"
                    dense
                    data-test="sr-log-execution"
                  />
                </div>
              </div>
            </div>
          </section>

          <!-- STEP 2 — Applies when -->
          <section class="rb-step">
            <div class="rb-step-head">
              <span class="rb-step-eyebrow">{{ $t('step') }} 2</span>
              <span class="rb-step-title">{{ $t('applies_when') }}</span>
              <span class="rb-step-hint">{{ $t('leave_empty_to_match_every_document') }}</span>
            </div>
            <div class="sr-when">
              <p v-if="!rule.group.conditions.length" class="sr-empty-note">
                {{ $t('no_conditions_matches_every_document', { docType }) }}
              </p>

              <!-- The SAME condition editor the validation and transformation
                   rule builders use: all/any join, per-field operators and value
                   pickers, and nested sub-groups. The tree it edits round-trips
                   through applies_when, so a group saves and reopens intact. -->
              <ConditionGroup
                :group="rule.group"
                :field-options="fieldOptions"
                :origin-options="originOptions"
                :sub-org-options="subOrgOptions"
                :lov-options="lovValueOptions"
              />
            </div>
          </section>

          <!-- STEP 3 — Target layout -->
          <section class="rb-step">
            <div class="rb-step-head">
              <span class="rb-step-eyebrow">{{ $t('step') }} 3</span>
              <span class="rb-step-title">{{ $t('target_layout') }}</span>
              <span class="rb-step-hint">{{ $t('what_the_document_gets') }}</span>
            </div>
            <div class="sr-target">
              <TargetLayoutPicker
