                :model-value="rule.layoutTemplateId"
                :selected-title="rule.targetTitle"
                :loading="layoutsLoading"
                :load-error="layoutsLoadError"
                :load-details="loadLayoutDetails"
                @update:model-value="onLayoutChange"
                @retry="loadLayouts"
              />
