            </div>
          </section>
        </div>

        <!-- Live preview — the same /resolve read-out the drawer showed. -->
        <aside class="sr-ed-aside">
          <div class="sr-pv-card">
            <div class="sr-pv-head">
              <Icon icon="mdi:pulse" />
              {{ $t('live_preview_resolve') }}
            </div>
            <div class="sr-pv-body">
              <div class="sr-kv">
                <span>{{ $t('sample_document') }}</span>
                <b class="mono">{{ previewSample }}</b>
              </div>
              <div class="sr-kv">
                <span>{{ $t('matched_by') }}</span>
                <span class="fb-sr-badge fb-sr-badge--custom">{{ $t('rule') }}</span>
              </div>
              <div class="sr-kv">
                <span>{{ $t('resolved_layout') }}</span>
                <b>{{ rule.targetTitle || '—' }}</b>
              </div>
              <div class="sr-kv">
                <span>{{ $t('priority_hit') }}</span>
                <b class="mono">{{ Number(rule.priority) || 0 }}</b>
              </div>
              <div>
                <span class="sr-watch-label">{{ $t('watched_fields') }}</span>
                <div class="sr-watch">
                  <span v-for="(c, ci) in watchedFields" :key="ci" class="fb-sr-chip">{{ c }}</span>
                  <span v-if="!watchedFields.length" class="sr-watch-none">—</span>
                </div>
              </div>
            </div>
          </div>
