        </aside>
      </div>
      </template>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { layout_types, isDefaultOrg } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import { formBuilderApiService } from 'src/services';
import Loader from 'src/components/Loader.vue';
import TargetLayoutPicker, { type TargetLayoutOption } from './components/TargetLayoutPicker.vue';
import { buildLayoutPreview } from './components/layout-preview.model';
import {
  buildFieldOptions,
  isBuilderGroup,
  loadDocOriginOptions,
  loadHeaderFieldOptions,
  loadLovValueOptions,
  type BuilderCondition,
  type BuilderGroup,
  type FieldOption,
} from 'src/pages/Settings/Components/CustomValidationRules/rule-builder-model';
import ConditionGroup from 'src/pages/Settings/Components/CustomValidationRules/ConditionGroup.vue';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';
import { useRuleKey } from 'src/pages/Settings/Components/CustomValidationRules/useRuleKey';
import {
  blankRule,
  normalizeRule,
  sentenceCase,
  buildRulePayload,
  createRuleKey,
  OP_SYMBOLS,
} from './components/selection-rules.model';
import type { EditingRule, TargetLayout } from './components/selection-rules.types';

const LAYOUT_TYPE = layout_types.field_validation;

// Symbols for the live-preview line, keyed by the canonical ConditionOp.
const OP_PREVIEW: Record<string, string> = {
  eq: '=',
  neq: '≠',
  gt: '>',
  lt: '<',
  gte: '≥',
  lte: '≤',
  in: 'in',
  not_empty: 'is set',
};

export default defineComponent({
  name: 'SelectionRuleEditor',
  components: { ConditionGroup, Loader, TargetLayoutPicker },
  data() {
    return {
      docType: '',
      layoutType: LAYOUT_TYPE,
      // Condition field picker options (doc.* + header.*).
      fieldOptions: [] as FieldOption[],
      // Value options for the doc.doc_origin / doc.sub_org_id condition rows,
      // loaded once and handed to the condition editor (which would otherwise
      // render those rows' value dropdowns empty).
      originOptions: [] as FieldOption[],
      subOrgOptions: [] as FieldOption[],
      lovValueOptions: {} as Record<string, FieldOption[]>,
      // Layout templates for this doc type + layout type — the Target layout
      // picker's option source.
      layouts: [] as TargetLayout[],
      layoutsLoading: false,
      layoutsLoadError: false,
    };
  },
  computed: {
    isEdit(): boolean {
      return !this.rule.isNew;
    },
    readableLayoutType(): string {
      return sentenceCase(this.layoutType);
    },
    // Layout templates mapped to searchable rows with optional origin and source.
    layoutOptions(): TargetLayoutOption[] {
      return this.layouts.map((l) => ({
        label: l.title,
        value: l.id,
        type: sentenceCase(l.layout_type),
        ...(l.doc_origin ? { origin: l.doc_origin } : {}),
        ...(l.org_id ? { source: this.$t(isDefaultOrg(l.org_id) ? 'sr_layout_system' : 'sr_layout_own') } : {}),
      }));
    },
    // Every leaf of the condition tree, depth-first — what the preview and the
    // watched-field chips read (a nested sub-group's rows count too).
    leafConditions(): BuilderCondition[] {
      const out: BuilderCondition[] = [];
      const walk = (group: BuilderGroup) => {
        for (const item of group.conditions) {
          if (isBuilderGroup(item)) walk(item);
          else out.push(item);
        }
      };
      walk(this.rule.group);
      return out;
    },
    // The summary banner's clauses: one per TOP-LEVEL item, so a sub-group reads
    // as a parenthesised unit joined by its own all/any rather than being
    // silently flattened into its parent's list.
    namedConditions(): string[] {
      return this.rule.group.conditions
        .map((item) => (isBuilderGroup(item) ? this.groupClause(item) : this.leafClause(item)))
        .filter(Boolean);
    },
    watchedFields(): string[] {
      return this.leafConditions.map((c) => c.field).filter(Boolean);
    },
    previewSample(): string {
      const first = this.leafConditions.find((c) => c.field);
      if (first) {
        const op = OP_PREVIEW[first.op] || first.op;
        if (first.op === 'not_empty') return `${first.field} ${op}`;
        return `${first.field} ${op} ${first.value}`.trim();
      }
      return this.docType || this.$t('sample_document_value');
    },
  },
  mounted() {
    this.docType = String(this.$route.params.doc_type || '');
    this.layoutType = String(this.$route.query.layout_type || LAYOUT_TYPE);
    this.rule = blankRule(this.layoutType);
    this.loadFieldOptions();
    this.loadLayouts();
    this.loadOrigins();
    this.loadSubOrgs();
    const ruleId = String(this.$route.params.rule_id || '');
    if (ruleId) {
      this.loadRule(ruleId);
    }
  },
  methods: {
    // Always read the rule from the server. The row the list hands over via
    // router state is a snapshot: it survives a refresh and Back/Forward, so
    // after a save it would reopen the editor on the pre-save values.
    async loadRule(ruleId: string) {
      try {
        this.loading = true;
        const response = (await formBuilderApiService.getLayoutSelectionRule(ruleId)) as dynamicObj;
        const raw = response && response.id ? response : (response?.data as dynamicObj | undefined);
        if (!raw || !raw.id) {
          notify.error(this.$t('rule_not_found'));
          this.goBack();
          return;
        }
        const ctx = { layoutType: this.layoutType, untitledLabel: this.$t('untitled_rule') };
        // Drop the list's flattened display mirror — the editor works on the
        // `group` tree (EditingRule omits both).
        const { conditions, match, ...carried } = normalizeRule(raw, 0, ctx);
        this.rule = { ...carried, isNew: false };
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError(err);
        this.goBack();
      } finally {
        this.loading = false;
      }
    },
    // Condition field picker options (doc.* + header.*) for this doc type.
    // Non-fatal: the editor still works, the picker just has no suggestions.
    async loadFieldOptions() {
      if (!this.docType) return;
      try {
        const headerFields = await loadHeaderFieldOptions(this.docType);
        this.fieldOptions = buildFieldOptions('header', headerFields, []);
        this.lovValueOptions = await loadLovValueOptions(headerFields);
      } catch (err) {
        logError(err);
      }
    },
    // Layout templates for this doc type + layout type. Same endpoint the
    // layouts panel uses; failed requests remain visible with a retry action.
    async loadLayouts() {
      if (!this.docType) return;
      this.layoutsLoading = true;
      this.layoutsLoadError = false;
      try {
        const response = (await formBuilderApiService.getAllLayoutTemplates({
          layout_type: this.layoutType,
          doc_type: this.docType,
          // scope 'all' includes the default-org layouts. Without it a seeded
          // rule targeting a system default has no option to match, and its
          // target picker renders as though nothing were selected.
          scope: 'all',
        })) as dynamicObj;
        this.layouts = (
          Array.isArray(response)
            ? response
            : Array.isArray(response?.data)
              ? response.data
              : []
        ) as TargetLayout[];
      } catch (err) {
        this.layoutsLoadError = true;
        logError(err);
      } finally {
        this.layoutsLoading = false;
      }
    },
    async loadLayoutDetails(id: string) {
      try {
        const response = await formBuilderApiService.getDocumentLayoutTemplateById(id);
        return buildLayoutPreview(response, (key, params) => this.$t(key, params || {}));
      } catch (err) {
        logError(err);
        throw err;
      }
    },
    // One leaf as a short readable clause. A row with no field chosen yet
    // contributes nothing to the summary.
    leafClause(c: BuilderCondition): string {
      if (!c.field) return '';
      const op = OP_SYMBOLS[c.op] || c.op;
      const clause =
        c.op === 'not_empty'
          ? `${c.field} ${this.$t('is_set')}`
          : `${c.field} ${op} ${c.value}`.trim();
      return c.negate ? `${this.$t('phrase_not')} ${clause}` : clause;
    },
    // A sub-group as a parenthesised clause, joined by ITS own all/any. Nests
    // as deep as the tree does.
    groupClause(group: BuilderGroup): string {
      const joiner = group.join === 'any' ? this.$t('or') : this.$t('and');
      const parts = group.conditions
        .map((item) => (isBuilderGroup(item) ? this.groupClause(item) : this.leafClause(item)))
        .filter(Boolean);
      return parts.length ? `(${parts.join(` ${joiner} `)})` : '';
    },
    // Keep the preview fields in sync with the picked layout so "Resolved layout"
    // reflects the new target immediately. The bound value (layoutTemplateId) is
    // what save serializes as layout_template_id.
    onLayoutChange(value: string) {
      this.rule.layoutTemplateId = value;
      const opt = this.layoutOptions.find((o) => o.value === value);
      this.rule.targetTitle = opt ? opt.label : '';
      this.rule.targetType = opt ? opt.type : this.rule.targetType;
    },
    // Value options for the doc.doc_origin rows — same shared source the
    // validation-rule builder uses. Non-fatal: the row falls back to an empty
    // picker.
    async loadOrigins() {
      try {
        this.originOptions = await loadDocOriginOptions();
      } catch (err) {
        logError(err);
      }
    },
    // Value options for the doc.sub_org_id rows, from the shared dropdown store.
    async loadSubOrgs() {
      try {
        const store = useDropdownStore();
        await store.getSubOrgsList();
        this.subOrgOptions = (store.subOrgList as dynamicObj[])
          .filter((o) => o && o.value)
          .map((o) => ({ value: String(o.value), label: String(o.label ?? o.value) }));
      } catch (err) {
        logError(err);
      }
    },
    // Same two endpoints the drawer's parent used, with the same bodies.
    async onSave() {
      if (this.saving) return;
      const rule = this.rule;
      const payload = buildRulePayload(rule);
      try {
        this.saving = true;
        if (rule.isNew) {
          await formBuilderApiService.createLayoutSelectionRule({
            doc_type_key: this.docType,
            sub_doc_type_key: '',
            layout_type: this.layoutType,
            rule_key: createRuleKey(rule),
            ...payload,
          });
        } else {
          await formBuilderApiService.updateLayoutSelectionRule(rule.id, payload);
        }
        notify.success(this.$t('operation_sucessfull'));
        this.goBack();
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as dynamicObj));
        logError(err);
      } finally {
        this.saving = false;
      }
    },
    goBack() {
      this.$router.push({
        path: `/settings/doc-type-settings/${this.docType}/layouts`,
        query: { screen: 'rules', layout_type: this.layoutType },
      });
    },
  },
  // setup() hosts the useRuleKey composable (composables must run here) plus the
  // state it reads reactively.
  setup() {
    const rule = ref<EditingRule>(blankRule(LAYOUT_TYPE));
    const ruleKey = useRuleKey({
      getName: () => rule.value.name,
      setKey: (value) => {
        rule.value.key = value;
      },
      isEdit: () => !rule.value.isNew,
    });
    return {
      rule,
      ...ruleKey,
      loading: ref(false),
      saving: ref(false),
    };
  },
});
</script>

